"""navera_lite/arbiter.py — the judge: which source to trust, and how much. Part of NAVERA Lite, the course's
teaching stack (mission 29; it replaces arbiter v0 of mission 09).
Written for the course; it is not NAVERA code.

The judge is a STATE MACHINE (lesson 29 §1): its answer depends on the inputs AND on a small memory that the
inputs update. The whole memory is in the Arbiter object, in plain sight:
    latest    source → the newest Estimate it STORED from that source (refused ones are never stored)
    refused   source → why its last fix was refused at the door (future stamp, jump), until one is stored
    since     source → the instant it became eligible, for the sources eligible WITHOUT a break since then
    current   the source that won the last decision (None: no winner)
    switches  every change of winner: (time, old source, new source)

Its rules (lesson 29; the values are in navera_lite.yaml):
  - the door (receive): an unknown source, a stamp that is not a finite number, a fix stamped in the future,
    a fix not newer than the stored one ("old news") and a GPS jump are refused, and a refused fix is NEVER stored: it cannot come back later;
  - eligible = estimate.eligible() (mission 12): valid, a real position, a covariance when one is stated,
    not from the future, fresh for its source's timeout;
  - priority GPS > day > night > celestial, with a HOLD-OFF: a higher-priority source takes over only after
    switch_holdoff_s of eligibility without a break; a winner that stops being eligible is replaced at once;
  - the state: STARTING before anything arrives, NO_FIX without a winner (the reason says why, source by
    source), else FIX if the winner states σ ≤ fix_max_sigma_m (estimate.stated_sigma), DEGRADED otherwise.
"""
import math
from dataclasses import dataclass, field

from navera_lite.estimate import SOURCES, TIMEOUT_KEY, Estimate, classify, eligible, stated_sigma
from navera_lite.geo import is_finite_latlon
from navera_lite.guard import JumpGate


# from mission 29 — finished: read it, use it, do not change it
@dataclass
class Decision:
    """One decision of the judge.

    state: "STARTING", "NO_FIX", "FIX" or "DEGRADED" · source: the winner ("gps", "day", …) or None ·
    estimate: the winner's Estimate or None · sigma_m: the σ the winner states (m), None if unknown or no
    winner · reason: one sentence for humans · sources: source → its situation in words ·
    switched: True when the winner changed at this decision.
    Example: Decision("FIX", "gps", est, 3.0, "gps: σ 3.0 m", {"gps": "eligible", …}, switched=True)
    """
    state: str
    source: str | None
    estimate: Estimate | None
    sigma_m: float | None
    reason: str
    sources: dict = field(default_factory=dict)
    switched: bool = False


# from mission 29 — finished: read it, use it, do not change it
def source_report(latest, refused, now_s, cfg):
    """Every source's situation in words (the status's src.<source> values and the NO_FIX reason).

    latest, refused: the Arbiter's memory (see the top of this file). Returns a dict source → text:
    "nothing received", the verdict of estimate.eligible() ("eligible", "stale (4.0 s > 3.0 s)", …),
    "refused: <why>" when the only fixes it sent were refused, or "<verdict>; last fix refused: <why>".
    Example: source_report({}, {"gps": "from the future (20.0 s ahead)"}, 100.0, DEFAULTS)["gps"]
             → "refused: from the future (20.0 s ahead)"
    """
    out = {}
    for name in SOURCES:
        est = latest.get(name)
        if est is None:
            text = f"refused: {refused[name]}" if name in refused else "nothing received"
        else:
            text = eligible(est, now_s, cfg)[1]
            if name in refused:
                text += f"; last fix refused: {refused[name]}"
        out[name] = text
    return out


# from mission 29 — finished: read it, use it, do not change it
def no_fix_reason(sources):
    """The reason of a NO_FIX decision: each source that sent something, in priority order, and its situation.

    Example: no_fix_reason({"gps": "stale (4.0 s > 3.0 s)", "day": "nothing received",
             "night": "nothing received", "celestial": "nothing received"})
             → "no usable source (gps: stale (4.0 s > 3.0 s))"
    """
    parts = [f"{name}: {sources[name]}" for name in SOURCES
             if sources.get(name, "nothing received") != "nothing received"]
    return "no usable source (" + "; ".join(parts) + ")"


