def candidates(latest, now_s, cfg):
    """The sources that may compete now: those whose stored estimate is eligible at now_s (estimate.eligible),
    in PRIORITY order (estimate.SOURCES: gps, day, night, celestial), whatever the order of the dict.

    latest: dict source → Estimate (a source that sent nothing is missing); now_s: the judge's clock (s);
    cfg: the settings. Returns a list of source names ([] when none is eligible).
    Example: candidates({"day": Estimate("day", 35.8, 10.6, 98.5), "gps": Estimate("gps", 35.8, 10.6, 96.0)},
             100.0, DEFAULTS) → ["day"]          (the GPS fix is 4.0 s old: stale, 3.0 s timeout)
    """
    return [name for name in SOURCES if name in latest and eligible(latest[name], now_s, cfg)[0]]


# from mission 29 — finished: read it, use it, do not change it
def track_since(since, cands, now_s):
    """The hold-off's memory, updated: for each source eligible NOW (cands), the instant it became eligible
    without a break since then. A source that was already in `since` keeps its old instant; a new candidate
    gets now_s; a source that is not a candidate any more is forgotten (its next eligibility starts again).

    since: dict source → time (s); cands: list of source names; now_s: s. Returns a NEW dict.
    Example: track_since({"day": 90.0, "night": 95.0}, ["gps", "day"], 100.0) → {"gps": 100.0, "day": 90.0}
    """
    return {name: since.get(name, now_s) for name in cands}


# from mission 29 — finished: read it, use it, do not change it
def pick(cands, current, since, now_s, cfg):
    """The winner among the candidates: priority with a hold-off (lesson §4). Returns a source name, or None.

    A source may REPLACE the current winner only after cfg["switch_holdoff_s"] of eligibility without a break
    (now_s − since[source] ≥ the hold-off). So the winner is the first candidate, in priority order, that is
    the current winner or has waited the hold-off. A current winner that is no longer a candidate (or no
    current winner at all) gives no hold-off: then the first candidate wins at once.
    cands: list in priority order; current: source name or None; since: from track_since(); now_s: s.
    Example: pick(["gps", "day"], "day", {"gps": 99.0, "day": 80.0}, 100.0, DEFAULTS) → "day"
             (GPS eligible for 1.0 s only, the hold-off is 2.0 s);  the same at now_s = 101.0 → "gps"
    """
    if current not in cands:
        return cands[0] if cands else None
    holdoff = float(cfg["switch_holdoff_s"])
    for name in cands:
        if name == current or now_s - since[name] >= holdoff:
            return name
    return current


# from mission 29 — finished: read it, use it, do not change it
class Arbiter:
    """The judge of NAVERA Lite (lesson 29). Feed it with receive(est, now_s) on every arrival; ask it with
    step(now_s) on every arrival and at tick_hz. Its memory is in its attributes (see the top of this file).

    Example: a = Arbiter(DEFAULTS); a.step(0.0).state → "STARTING"
    """

    def __init__(self, cfg):
        self.cfg = dict(cfg)
        self.gate = JumpGate(self.cfg)       # mission 01's jump gate, on GPS fixes only
        self.latest = {}                     # source → newest stored Estimate
        self.refused = {}                    # source → why its last fix was refused at the door
        self.since = {}                      # source → instant it became eligible (no break since)
        self.current = None                  # the last winner (None: no winner)
        self.switches = []                   # (time s, old source, new source) at every change of winner

    # from mission 29 — finished: read it, use it, do not change it
    def receive(self, est, now_s):
        """The door: STORE this new estimate as the newest of its source, or refuse it. Returns (stored, why).

        Refused, in this order (nothing is stored, and a refused fix can never come back later):
          - a source with no timeout (not in estimate.TIMEOUT_KEY):  (False, "unknown source 'radar'")
          - a stamp that is not a finite number (nan, inf):          (False, "bad stamp")
          - stamped over cfg["future_tolerance_s"] after now_s:      (False, "from the future (20.0 s ahead)")
            — for these two, remember the reason in self.refused[source]
          - a stamp not newer than the one stored for that source:   (False, "old news")
          - a GPS fix with a real position (valid, finite) that the jump gate (self.gate.check) refuses:
            (False, the gate's reason) — remember it in self.refused["gps"]
        Otherwise: record now_s in est.t_recv_s (when it arrived), store it in self.latest, forget the
        source's refusal and return (True, "stored"). A fix with valid False is stored: the source is alive
        and says "no position".
        Example: a = Arbiter(DEFAULTS); a.receive(Estimate("gps", 35.8, 10.6, 120.0), 100.0)
                 → (False, "from the future (20.0 s ahead)")   and a.latest is still {}
        """
        name = est.source
        if name not in TIMEOUT_KEY:
            return False, f"unknown source {name!r}"
        if not math.isfinite(est.stamp_s):
            self.refused[name] = "bad stamp"
            return False, "bad stamp"
        ahead = est.stamp_s - now_s
        if ahead > float(self.cfg["future_tolerance_s"]):
            why = f"from the future ({ahead:.1f} s ahead)"
            self.refused[name] = why
            return False, why
        old = self.latest.get(name)
        if old is not None and est.stamp_s <= old.stamp_s:
            return False, "old news"
        if name == "gps" and est.valid and is_finite_latlon(est.lat, est.lon):
            ok, why = self.gate.check(est)
            if not ok:
                self.refused[name] = why
                return False, why
        est.t_recv_s = now_s
        self.refused.pop(name, None)
        self.latest[name] = est
        return True, "stored"

    # from mission 29 — finished: read it, use it, do not change it
    def step(self, now_s):
        """One decision of the judge at now_s (lesson §5), and its memory kept up to date. Returns a Decision.

        The decision, by situation:
          nothing received yet (nothing stored or refused)  "STARTING", reason "no position received yet"
          no winner                                         "NO_FIX", reason no_fix_reason(sources)
          a winner                                          "FIX" or "DEGRADED" from the σ the winner states
                                                            (estimate.stated_sigma, then estimate.classify),
                                                            reason "<source>: <classify's words>"
        The winner is pick()'s (TODO 3) among the candidates (TODO 1), with the hold-off memory self.since
        brought up to date first (TODO 2). Every change of winner (None included) is appended to self.switches
        as (now_s, old, new) and flagged switched=True; self.current always holds the latest winner.
        sources = source_report(self.latest, self.refused, now_s, self.cfg) in every Decision.
        Example: after a.receive(Estimate("gps", 35.8, 10.6, 99.5, cov=(9.0, 0, 0, 0, 9.0, 0, 0, 0, 36.0),
                 cov_type=1), 100.0), a.step(100.0) → Decision(state="FIX", source="gps", sigma_m=3.0,
                 reason="gps: σ 3.0 m", switched=True, …)   and a.switches == [(100.0, None, "gps")]
        """
        sources = source_report(self.latest, self.refused, now_s, self.cfg)
        if not self.latest and not self.refused:
            return Decision("STARTING", None, None, None, "no position received yet", sources)
        cands = candidates(self.latest, now_s, self.cfg)
        self.since = track_since(self.since, cands, now_s)
        winner = pick(cands, self.current, self.since, now_s, self.cfg)
        switched = winner != self.current
        if switched:
            self.switches.append((now_s, self.current, winner))
            self.current = winner
        if winner is None:
            return Decision("NO_FIX", None, None, None, no_fix_reason(sources), sources, switched)
        est = self.latest[winner]
        sigma = stated_sigma(est, self.cfg)
        state, words = classify(sigma, self.cfg)
        return Decision(state, winner, est, sigma, f"{winner}: {words}", sources, switched)
